import whisper
import json
import re

def detect_fillers(audio_path):
    print(f"Loading model...")
    model = whisper.load_model("tiny")
    print(f"Transcribing {audio_path}...")
    # Using tiny model, FP32 for CPU
    result = model.transcribe(audio_path, word_timestamps=True, fp16=False)
    print(f"Transcription finished. Detecting fillers...")

    fillers = [
        "um", "uh", "hum", "hmm", "mhm",
        "like", "yeah", "so", "basically", "well", "okay"
    ]
    phrases = [
        (["you", "know"], "you know"),
        (["i", "mean"], "i mean"),
        (["kind", "of"], "kind of"),
        (["i", "guess"], "I guess")
    ]

    annotations = []

    all_words = []
    for segment in result['segments']:
        if 'words' in segment:
            for word_info in segment['words']:
                all_words.append(word_info)

    print(f"Found {len(all_words)} words. Checking for fillers...")
    i = 0
    while i < len(all_words):
        found_phrase = False
        for phrase_words, phrase_label in phrases:
            if i + len(phrase_words) <= len(all_words):
                match = True
                for j in range(len(phrase_words)):
                    w = re.sub(r'[^\w]', '', all_words[i+j]['word'].lower())
                    if w != phrase_words[j]:
                        match = False
                        break
                if match:
                    annotations.append({
                        "word": phrase_label,
                        "timestamp": all_words[i]['start'],
                        "end": all_words[i+len(phrase_words)-1]['end']
                    })
                    i += len(phrase_words)
                    found_phrase = True
                    break

        if not found_phrase:
            word_text = re.sub(r'[^\w]', '', all_words[i]['word'].lower())
            if word_text in fillers:
                annotations.append({
                    "word": all_words[i]['word'].strip().strip(',.?!'),
                    "timestamp": all_words[i]['start'],
                    "end": all_words[i]['end']
                })
            i += 1

    return annotations

if __name__ == "__main__":
    audio_path = "/root/input.mp3"
    annotations = detect_fillers(audio_path)
    with open("/root/annotations.json", "w") as f:
        json.dump(annotations, f, indent=2)
    print(f"Saved {len(annotations)} fillers to /root/annotations.json")

